def transform(grid):
    h, w = len(grid), len(grid[0])
    fours = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 4]
    sixes = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 6]
    out = [row[:] for row in grid]

    for r, c in sixes:
        out[r][c] = 0

    rmin = min(r for r, c in fours)
    rmax = max(r for r, c in fours)
    cmin = min(c for r, c in fours)
    cmax = max(c for r, c in fours)

    srmin = min(r for r, c in sixes)
    srmax = max(r for r, c in sixes)
    scmin = min(c for r, c in sixes)
    scmax = max(c for r, c in sixes)

    # A T-shaped marker indicates a left-right reflection; the cross-like
    # marker indicates an up-down reflection.
    rows = {r: {c for rr, c in sixes if rr == r} for r in range(srmin, srmax + 1)}
    cols = {c: {r for r, cc in sixes if cc == c} for c in range(scmin, scmax + 1)}
    full_width_rows = [r for r, cs in rows.items() if len(cs) == scmax - scmin + 1]
    t_marker = False
    if full_width_rows:
        bar = full_width_rows[0]
        stem_col = max(range(scmin, scmax + 1), key=lambda c: sum((r, c) in sixes for r in range(srmin, srmax + 1)))
        t_marker = bar in (srmin, srmax) and sum((r, stem_col) in sixes for r in range(srmin, srmax + 1)) >= 2

    if t_marker:
        marker_c = sum(c for r, c in sixes) / len(sixes)
        shape_c = sum(c for r, c in fours) / len(fours)
        if marker_c < shape_c:
            for r, c in fours:
                cc = 2 * cmin - 1 - c
                if 0 <= cc < w:
                    out[r][cc] = 4
        else:
            for r, c in fours:
                cc = 2 * cmax + 1 - c
                if 0 <= cc < w:
                    out[r][cc] = 4
    else:
        marker_r = sum(r for r, c in sixes) / len(sixes)
        shape_r = sum(r for r, c in fours) / len(fours)
        if marker_r < shape_r:
            for r, c in fours:
                rr = 2 * rmin - 1 - r
                if 0 <= rr < h:
                    out[rr][c] = 4
        else:
            for r, c in fours:
                rr = 2 * rmax + 1 - r
                if 0 <= rr < h:
                    out[rr][c] = 4

    return out
